WITH src AS (SELECT *, COALESCE(carrier, 'N/A') AS carrier_filled FROM shipments WHERE MONTH(delivered_date) IN (1, 7, 8) AND carrier IN ('UPS', 'FedEx') AND order_id IN (7, 31, 32, 35)), agg AS (SELECT YEAR(shipped_date) AS shipped_year, status, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(carrier))) AS carrier_values, COUNT(cost) AS cost_count FROM src GROUP BY YEAR(shipped_date), status) SELECT * FROM agg ORDER BY status;
